/** `ps -o etime` (`[[dd-]hh:]mm:ss`) in milliseconds; 0 when it is not that. */
export function etimeMs(text: string): number {
  const match = /^(?:(\d+)-)?(?:(\d+):)?(\d+):(\d+)$/.exec(text.trim())
  if (match === null) return 0
  const [, days, hours, minutes, seconds] = match
  return (((Number(days ?? 0) * 24 + Number(hours ?? 0)) * 60 + Number(minutes)) * 60 + Number(seconds)) * 1000
}

export type ProcessRow = { pid: number; ppid: number; elapsedMs: number; command: string }

/** The rows of `ps -A -ww -o pid=,ppid=,etime=,command=`. */
export function parsePs(text: string): ProcessRow[] {
  const rows: ProcessRow[] = []
  for (const line of text.split('\n')) {
    const match = /^\s*(\d+)\s+(\d+)\s+(\S+)\s+(.*)$/.exec(line)
    if (match === null) continue
    rows.push({ pid: Number(match[1]), ppid: Number(match[2]), elapsedMs: etimeMs(match[3] ?? ''), command: match[4] ?? '' })
  }
  return rows
}

const SHELL = '/bin/sh -c '

/**
 * The driver's verify, when one runs: its `/bin/sh -c a && b && c` child, how
 * long it has run, and which step its own child is — the first step whose
 * every word, flags aside, appears in that child's command line.
 */
export function verifyingOf(rows: ProcessRow[], driverPid: number): DriveVerify | undefined {
  const shell = rows.find(row => row.ppid === driverPid && row.command.startsWith(SHELL))
  if (shell === undefined) return undefined
  const steps = shell.command.slice(SHELL.length).split('&&').map(step => step.trim()).filter(step => step.length > 0)
  const child = rows.find(row => row.ppid === shell.pid)
  const at =
    child === undefined
      ? -1
      : steps.findIndex(step => step.split(/\s+/).filter(word => !word.startsWith('-')).every(word => child.command.includes(word)))
  return { elapsedMs: shell.elapsedMs, steps: steps.length, ...(at >= 0 ? { step: at + 1, doing: steps[at] ?? '' } : {}) }
}

export type PhaseView = { phase: PlanPhase; tasks: PlanTask[]; hidden: number }

/**
 * The plan in `rows` rows: every phase's line, then tasks while rows are
 * left, the live task first, then the first open phase's, the live phase's,
 * the later open phases' and the rest. Each phase keeps its tasks in plan order.
 */
export function fitPlan(plan: PlanPhase[], liveTask: string | null, rows: number): PhaseView[] {
  const isOpen = (phase: PlanPhase) => phase.status !== 'done' && phase.status !== 'dropped'
  const firstOpen = plan.find(phase => isOpen(phase) && phase.tasks.some(task => task.status !== 'done' && task.status !== 'dropped'))
  const live = plan.find(phase => phase.tasks.some(task => task.id === liveTask))
  const order = [
    ...plan.flatMap(phase => phase.tasks).filter(task => task.id === liveTask),
    ...(firstOpen?.tasks ?? []),
    ...(live?.tasks ?? []),
    ...plan.filter(isOpen).flatMap(phase => phase.tasks),
    ...plan.flatMap(phase => phase.tasks),
  ]
  const shown = new Set<string>()
  let left = rows - plan.length
  for (const task of order) {
    if (left <= 0) break
    if (shown.has(task.id)) continue
    shown.add(task.id)
    left -= 1
  }
  return plan.map(phase => {
    const tasks = phase.tasks.filter(task => shown.has(task.id))
    return { phase, tasks, hidden: phase.tasks.length - tasks.length }
  })
}
